// Explorer avatar: a tiny brass-and-ivory wayfinder.
const player=new THREE.Group();group.add(player);const shadow=new THREE.Mesh(new THREE.CircleGeometry(.37,20),new THREE.MeshBasicMaterial({color:0x06121a,transparent:true,opacity:.48}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.018;player.add(shadow);
const body=add(new THREE.CapsuleGeometry(.29,.48,5,8),mats.white,player);body.position.y=.57;const scarf=add(new THREE.TorusGeometry(.24,.065,7,18),mats.gold,player);scarf.rotation.x=Math.PI/2;scarf.position.y=.62;const head=add(new THREE.SphereGeometry(.21,12,10),mats.white,player);head.position.set(0,.99,0);const visor=add(new THREE.SphereGeometry(.15,10,8),mats.cyan,player);visor.scale.set(1,.52,.45);visor.position.set(0,1.01,-.15);const pack=add(new THREE.BoxGeometry(.24,.34,.19),mats.gold,player);pack.position.set(0,.57,.29);
const portalMat=new THREE.MeshBasicMaterial({color:0x6cf4e8,transparent:true,opacity:.88});let activePortal=null;let portalRing=null;let portalInner=null;let portalGlow=null;
function makePortal(p){if(portalRing)group.remove(portalRing);if(portalInner)group.remove(portalInner);if(portalGlow)group.remove(portalGlow);portalRing=new THREE.Mesh(new THREE.TorusGeometry(.61,.085,10,40),portalMat);portalRing.rotation.x=Math.PI/2;portalRing.position.set(p.x,.3,p.z);group.add(portalRing);portalInner=new THREE.Mesh(new THREE.CircleGeometry(.55,40),new THREE.MeshBasicMaterial({color:0x37cfc5,transparent:true,opacity:.26,side:THREE.DoubleSide}));portalInner.rotation.x=-Math.PI/2;portalInner.position.set(p.x,.22,p.z);group.add(portalInner);portalGlow=new THREE.PointLight(0x55ffe9,1.7,6);portalGlow.position.set(p.x,1,p.z);group.add(portalGlow);activePortal=p;}
let position=new THREE.Vector3(-3,0,1),moveDir=new THREE.Vector3(),keys=new Set(),jumpTime=0,portalUsed=false,won=false,startedAt=performance.now(),lastTime=0,lastInteract=0,toastTimer=0;
player.position.copy(position);const hintEl=document.getElementById('hint'),toastEl=document.getElementById('toast'),countEl=document.getElementById('shardCount'),fillEl=document.getElementById('meterFill'),percentEl=document.getElementById('percent'),portalStatus=document.getElementById('portalStatus'),portalLabel=document.getElementById('portalLabel');
function showToast(t){toastEl.textContent=t;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function groundedAt(x,z){return solids.some(p=>x>=p.x-p.w/2+.24&&x<=p.x+p.w/2-.24&&z>=p.z-p.d/2+.24&&z<=p.z+p.d/2-.24)}
function nearestThing(){let nearest=null,dist=2.05;for(const s of sockets){const d=Math.hypot(position.x-s.x,position.z-s.z);if(!activePortal&&d<dist){nearest={type:'socket',target:s,d};dist=d}}if(activePortal){const candidates=[{type:'portal',x:activePortal.x,z:activePortal.z},{type:'home',x:0,z:0}];for(const c of candidates){const d=Math.hypot(position.x-c.x,position.z-c.z);if(d<dist){nearest={type:c.type,target:c,d};dist=d}}}return nearest}
function refreshHint(){if(won)return;const n=nearestThing();if(n){hintEl.innerHTML=n.type==='socket'?'<span class="hint-key">E</span>Place your <em>one portal</em> · '+n.target.label:n.type==='home'?'<span class="hint-key">E</span>Enter the <em>return beacon</em>':'<span class="hint-key">E</span>Step through your <em>portal</em>';hintEl.classList.add('show')}else{hintEl.classList.remove('show')}}
function useAction(){if(won)return;const now=performance.now();if(now-lastInteract<320)return;lastInteract=now;const n=nearestThing();if(!n){showToast(activePortal?'Find a portal ring or the beacon':'Move close to a socket to place your portal');return}if(n.type==='socket'){makePortal(n.target);n.target.placed=true;n.target.mesh.material=mats.cyan;n.target.mesh.scale.setScalar(.3);portalStatus.classList.add('ready');portalLabel.textContent='One portal · '+n.target.label.toLowerCase();showToast('Portal anchored · your single gate is ready')}else if(n.type==='portal'){position.set(0,0,0);player.position.copy(position);portalUsed=true;showToast('Return beacon reached · keep moving')}else{position.set(activePortal.x,0,activePortal.z);player.position.copy(position);portalUsed=true;showToast('Portal crossed · one way back is all you get')}refreshHint();}
function collectShards(){for(const s of shards){if(!s.got&&Math.hypot(position.x-s.x,position.z-s.z)<.83){s.got=true;s.mesh.visible=false;s.halo.visible=false;group.remove(s.mesh);showToast('Memory shard recovered');const n=shards.filter(a=>a.got).length;countEl.textContent=n+' / 3 recovered';const pc=Math.round(n/3*100);fillEl.style.width=pc+'%';percentEl.textContent=String(pc).padStart(2,'0')+'%';if(n===3){document.querySelector('.panel h2').innerHTML='All memories.<br>Find the beacon.';showToast('All memories recovered · return to the beacon')}}}}
function checkWin(){if(shards.every(s=>s.got)&&portalUsed&&Math.hypot(position.x,position.z)<1.2){won=true;document.getElementById('winOverlay').classList.add('open')}}
function jump(){if(jumpTime<=0)jumpTime=.62}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(k==='e')useAction();if(k===' '||k==='spacebar')jump()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
document.querySelectorAll('.touchkey[data-key]').forEach(b=>{const k=b.dataset.key;const on=e=>{e.preventDefault();keys.add(k);b.setPointerCapture?.(e.pointerId)};const off=e=>{e.preventDefault();keys.delete(k)};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('lostpointercapture',off)});document.getElementById('mobileUse').addEventListener('pointerdown',e=>{e.preventDefault();useAction()});
function resetGame(){position.set(-3,0,1);player.position.copy(position);shards.forEach(s=>{s.got=false;s.mesh.visible=true;s.halo.visible=true;group.add(s.mesh)});sockets.forEach(s=>{s.placed=false;s.mesh.material=mats.white;s.mesh.scale.setScalar(1)});if(portalRing){group.remove(portalRing);group.remove(portalInner);group.remove(portalGlow)}activePortal=portalRing=portalInner=portalGlow=null;portalUsed=false;won=false;countEl.textContent='0 / 3 recovered';fillEl.style.width='0%';percentEl.textContent='00%';portalStatus.classList.remove('ready');portalLabel.textContent='One portal · unplaced';document.querySelector('.panel h2').innerHTML='Bring the light<br>back home.';document.getElementById('winOverlay').classList.remove('open');showToast('Find a socket · choose where to anchor your one portal')}
document.getElementById('resetBtn').addEventListener('click',resetGame);document.getElementById('playAgain').addEventListener('click',resetGame);
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);
function animate(time){requestAnimationFrame(animate);const dt=Math.min(.04,(time-lastTime)/1000||.016);lastTime=time;const now=time*.001;
 const dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dz=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);moveDir.set(dx,0,dz);if(moveDir.lengthSq()>0){moveDir.normalize();const speed=4.05;const nx=position.x+moveDir.x*speed*dt,nz=position.z+moveDir.z*speed*dt;if(groundedAt(nx,position.z))position.x=nx;if(groundedAt(position.x,nz))position.z=nz;player.rotation.y=Math.atan2(moveDir.x,moveDir.z)}
 if(jumpTime>0)jumpTime=Math.max(0,jumpTime-dt);const hop=jumpTime>0?Math.sin((.62-jumpTime)/.62*Math.PI)*.52:0;player.position.set(position.x,hop,position.z);shadow.material.opacity=.48-hop*.34;
 for(const s of shards){if(!s.got){s.mesh.rotation.y+=dt*.82;s.mesh.position.y=s.baseY+Math.sin(now*2.1+s.x)*.1;s.halo.material.opacity=.5+Math.sin(now*3+s.z)*.2}}
 for(const s of sockets){if(!s.placed){s.mesh.rotation.z+=dt*.35;s.mesh.position.y=.43+Math.sin(now*1.6+s.x)*.055}}
 if(portalRing){portalRing.rotation.z=now*.55;portalInner.material.opacity=.18+Math.sin(now*2)*.08;portalGlow.intensity=1.35+Math.sin(now*3)*.35}
 beaconCore.rotation.y=now*.65;beaconCore.position.y=1.1+Math.sin(now*2)*.09;beaconRing.material.opacity=.56+Math.sin(now*2.5)*.17;
 const target=new THREE.Vector3(position.x+1,0,position.z+10.2);camera.position.lerp(target,1-Math.pow(.001,dt));camera.lookAt(position.x,0,position.z-1.6);refreshHint();collectShards();checkWin();renderer.render(scene,camera)}
showToast('Find a socket · choose where to anchor your one portal');animate(performance.now());
</script>
</body>
</html>

